mapper.select:
SELECT sc.id, sc.course_id, c.course_code, c.course_name, sc.student_id, st.student_no, st.name AS student_name, cl.class_name, c.semester_id, se.semester_name, sc.usual_score, sc.exam_score, sc.final_score FROM score sc JOIN course c ON sc.course_id = c.id JOIN student st ON sc.student_id = st.id LEFT JOIN class_info cl ON st.class_id = cl.id JOIN semester se ON c.semester_id = se.id
AND c.semester_id = #{semesterId}
AND sc.course_id = #{courseId}
AND sc.student_id = #{studentId}
AND c.teacher_id = #{teacherId}
AND (st.student_no LIKE CONCAT('%', #{keyword}, '%') OR st.name LIKE CONCAT('%', #{keyword}, '%') OR c.course_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY se.start_date DESC, c.course_code, st.student_no
